<div class="page-heading"><div><span class="eyebrow">Groupe professionnel</span><h1>Effectif</h1><p><?= count($players) ?> joueurs · cliquez sur les en-têtes pour trier</p></div><a class="btn btn--ghost" href="/saves/<?= (int)$context->saveId() ?>/tactics">Configurer la tactique</a></div>
<section class="panel"><div class="table-toolbar"><input type="search" placeholder="Rechercher un joueur…" data-table-filter="squad-table"><div class="legend"><span class="rating rating--high">75+</span><span class="rating rating--mid">60</span><span class="rating rating--low">45</span></div></div><div class="table-wrap"><table class="table table--sortable" id="squad-table"><thead><tr><th data-sort>Joueur</th><th data-sort>Poste</th><th data-sort>Âge</th><th data-sort>OVR</th><th data-sort>Pot.</th><th data-sort>Forme</th><th data-sort>Moral</th><th data-sort>Fatigue</th><th data-sort>Valeur</th><th>Statut</th></tr></thead><tbody><?php foreach ($players as $player): ?><tr><td data-filter><a class="player-link" href="/saves/<?= (int)$context->saveId() ?>/players/<?= (int)$player['id'] ?>"><span class="avatar"><?= e(substr($player['first_name'],0,1).substr($player['last_name'],0,1)) ?></span><span><strong><?= e($player['first_name'].' '.$player['last_name']) ?></strong><small><?= e($player['nationality']) ?></small></span></a></td><td><span class="position-badge"><?= e($player['primary_position']) ?></span></td><td data-value="<?= player_age($player['birth_date'],$save['current_date']) ?>"><?= player_age($player['birth_date'],$save['current_date']) ?></td><td data-value="<?= (int)$player['overall_rating'] ?>"><span class="rating rating--<?= $player['overall_rating']>=75?'high':($player['overall_rating']>=60?'mid':'low') ?>"><?= (int)$player['overall_rating'] ?></span></td><td><?= (int)$player['potential'] ?></td><td><div class="mini-bar"><span style="width:<?= (int)$player['form'] ?>%"></span></div><?= (int)$player['form'] ?>%</td><td><?= (int)$player['morale'] ?>%</td><td><?= (int)$player['fatigue'] ?>%</td><td data-value="<?= (float)$player['market_value'] ?>"><?= format_money($player['market_value']) ?></td><td><?php if ($player['injury_type']): ?><span class="badge badge--danger" title="<?= e($player['injury_type']) ?>">Blessé · <?= format_date($player['injury_until'],'d/m') ?></span><?php elseif ($player['fatigue'] > 75): ?><span class="badge badge--warning">Fatigué</span><?php else: ?><span class="badge badge--success">Disponible</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
